package org.humanjourney.core.geography.map;
import java.util.*;
import java.nio.file.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import org.objectweb.asm.*;
import org.objectweb.asm.tree.*;
import org.humanjourney.core.integration.xaero.XaeroStatus;
import org.humanjourney.core.geography.client.GeographyClientConfig;
import com.electronwill.nightconfig.core.CommentedConfig;

class XaeroStructureTest {
 static Path root(){return Path.of(System.getProperty("humanjourney.projectDir"));}
 static ClassNode node(String name)throws Exception{try(var stream=XaeroStructureTest.class.getClassLoader().getResourceAsStream(name+".class")){assertNotNull(stream,name);var n=new ClassNode();new ClassReader(stream).accept(n,0);return n;}}
 @Test void exactVersionGateRejectsAbsentFutureAndDedicated(){assertTrue(XaeroStatus.supported(true,"1.39.13"));assertFalse(XaeroStatus.supported(true,null));assertFalse(XaeroStatus.supported(true,"1.39.14"));assertFalse(XaeroStatus.supported(false,"1.39.13"));}
 @Test void unsupportedAndAbsentDisableOnlyAdapter(){XaeroStatus.detect(null);assertFalse(XaeroStatus.state().detected());assertFalse(XaeroStatus.state().active());XaeroStatus.detect("9.0");assertFalse(XaeroStatus.state().supported());assertTrue(XaeroStatus.state().reason().contains("Unsupported"));XaeroStatus.detect("1.39.13");assertTrue(XaeroStatus.state().supported());}
 @Test void renderFailureStaysDisabledForSession(){XaeroStatus.detect("1.39.13");XaeroStatus.observed();assertTrue(XaeroStatus.state().active());XaeroStatus.disable(new IllegalStateException("synthetic"));XaeroStatus.observed();assertFalse(XaeroStatus.state().active());assertTrue(XaeroStatus.failed());XaeroStatus.detect(null);}
 @Test void inspectedExactArtifactHasExpectedCameraAndRenderHook()throws Exception{var n=node("xaero/map/gui/GuiMap");for(String name:new String[]{"cameraX","cameraZ","scale"})assertTrue(n.fields.stream().anyMatch(f->f.name.equals(name)&&f.desc.equals("D")),name);assertTrue(n.methods.stream().anyMatch(m->m.name.equals("renderPreDropdown")&&m.desc.equals("(Lnet/minecraft/client/gui/GuiGraphics;IIF)V")));for(String name:new String[]{"getMapProcessor","getFutureDimension"})assertTrue(n.methods.stream().anyMatch(m->m.name.equals(name)&&(m.access&Opcodes.ACC_PUBLIC)!=0),name);for(String name:new String[]{"viewed","rightClickMenu","overWaypointsMenu","overPlayersMenu"})assertTrue(n.fields.stream().anyMatch(f->f.name.equals(name)),name);}
 @Test void inspectedExactArtifactExposesDimensionAndMouseAccessors()throws Exception{for(var pair:List.of(new String[]{"xaero/map/MapProcessor","getMapWorld"},new String[]{"xaero/map/world/MapWorld","getCurrentDimension"},new String[]{"xaero/map/world/MapDimension","getDimId"},new String[]{"xaero/map/misc/Misc","getMouseX"},new String[]{"xaero/map/misc/Misc","getMouseY"})){assertTrue(node(pair[0]).methods.stream().anyMatch(m->m.name.equals(pair[1])&&(m.access&Opcodes.ACC_PUBLIC)!=0),Arrays.toString(pair));}}
 @Test void commonMapBytecodeHasNoClientOrXaeroTypeReferences()throws Exception{for(String name:new String[]{"MapArea","MapProjection","MapSpatialIndex","MapViewTransform","MapPackets","ClientMapState","MapNetwork","MapServer","MapBootstrap","MapSmoke"}){var n=node("org/humanjourney/core/geography/map/"+name);for(var f:n.fields)check(f.desc,name);for(var m:n.methods){check(m.desc,name);for(var i:m.instructions){if(i instanceof MethodInsnNode call){check(call.owner,name);check(call.desc,name);}if(i instanceof FieldInsnNode f){check(f.owner,name);check(f.desc,name);}if(i instanceof TypeInsnNode t)check(t.desc,name);}}}}
 static void check(String type,String name){assertFalse(type.contains("xaero/map/"),name+": "+type);assertFalse(type.contains("net/minecraft/client/"),name+": "+type);}
 @Test void mixinIsOptionalClientOnlyAndDoesNotInterceptInput()throws Exception{String config=Files.readString(root().resolve("src/main/resources/human_journey_core.xaero.mixins.json"));var json=com.google.gson.JsonParser.parseString(config).getAsJsonObject();assertFalse(json.get("required").getAsBoolean());assertEquals("GuiMapMixin",json.getAsJsonArray("client").get(0).getAsString());String source=Files.readString(root().resolve("src/main/java/org/humanjourney/core/integration/xaero/mixin/GuiMapMixin.java"));assertTrue(source.contains("renderPreDropdown"));assertFalse(source.contains("cancellable=true"));assertFalse(source.contains("mouseClicked"));String plugin=Files.readString(root().resolve("src/main/java/org/humanjourney/core/integration/xaero/XaeroMixinPlugin.java"));assertTrue(plugin.contains("Dist.CLIENT"));assertTrue(plugin.contains("XaeroStatus.supported"));}
 @Test void hudRegistrationRemainsIndependentAndClientDefaultsAreSubtle()throws Exception{String source=Files.readString(root().resolve("src/main/java/org/humanjourney/core/geography/client/GeographyClient.java"));assertTrue(source.contains("AddGuiOverlayLayersEvent"));assertFalse(source.contains("xaero.map"));assertEquals(true,GeographyClientConfig.MAP_ENABLED.getDefault());assertEquals(true,GeographyClientConfig.MAP_OUTLINES.getDefault());assertEquals(true,GeographyClientConfig.MAP_HOVER.getDefault());assertEquals(.4,GeographyClientConfig.MAP_OPACITY.getDefault());assertEquals(1.0,GeographyClientConfig.MAP_WIDTH.getDefault());var c=CommentedConfig.inMemory();c.set("world_map_geography.world_map_outline_width",2.5);c.set("world_map_geography.world_map_outline_opacity",.15);GeographyClientConfig.SPEC.correct(c);assertEquals(2.5,c.<Number>get("world_map_geography.world_map_outline_width").doubleValue());assertEquals(.15,c.<Number>get("world_map_geography.world_map_outline_opacity").doubleValue());assertEquals(85,c.<Number>get("geography_hud.x_offset").intValue());}
}
